{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C24"],
      "claim": "Omadacycline, a complex polycyclic natural product, has an absolute oral bioavailability of 34.5% in humans after a 300-mg tablet dose versus IV, supporting F≥20% for a similarly complex lactone-rich scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "CGP 43371, a large macrolide with a pivaloyl ester and very poor aqueous solubility, had only 9% oral bioavailability; this is the clearest low-F analogue but its much larger size and <1 µg/mL solubility limit transfer to the smaller query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C73"],
      "claim": "Hydrocortisone, a polycyclic terpenoid-like steroid, showed absolute oral bioavailability of 0.88 (95% CI 0.75-1.05) from a tablet versus IV, supporting high F for a rigid polycyclic molecule.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "9-Aminocamptothecin, a pentacyclic lactone natural product, had oral bioavailability of 49% ± 18% in patients, showing that lactone-rich poorly soluble scaffolds can exceed the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C30"],
      "claim": "Dihydroartemisinin, a polycyclic sesquiterpene lactone/acetal, showed high oral bioavailability (>80%) in humans, supporting high F for a complex oxygenated polycyclic natural product.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C63"],
      "claim": "Ixabepilone, a macrocyclic lactone, had an estimated absolute oral bioavailability of 36.6% across studied doses, supporting F≥20% for complex lactone-containing macrocycles.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C46"],
      "claim": "Etoposide, a polycyclic lactone glycoside, had mean absolute oral bioavailability of 47 ± 11% in patients, supporting high F for a complex lactone-rich scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C55"],
      "claim": "Erythromycin, a macrolide lactone, had absolute oral bioavailability of 32 ± 7% in healthy subjects, still above the 20% threshold despite being considered poorly absorbed.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Idarubicin, a complex polycyclic aromatic natural product, had median oral bioavailability of 29% (range 12-49%), supporting F≥20% for complex natural products with absorption limitations.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted high (F≥20%): the preponderance of transferable experimental evidence from complex polycyclic/macrocyclic lactone natural products shows absolute oral bioavailability around 25-80%, while the only clear low-F analogue is a much larger, extremely poorly soluble macrolide with limited transferability to the query.",
  "evidence_gaps": [
    "No direct absolute bioavailability measurement exists for the exact query or a close triptolide analogue.",
    "Aqueous solubility and transporter/first-pass metabolism of the query are not directly measured; the low-F CGP 43371 record is confounded by its very large size and <1 µg/mL solubility.",
    "The mefloquine enantiomer record is indirect and not a threshold-relevant absolute F measurement."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

